function Test-LeapYear {
    [CmdletBinding()]
    Param(
        [int]$Year
    )

    return (Test-DivisibleBy $Year 4) -and (-not (Test-DivisibleBy $Year 100) -or (Test-DivisibleBy $Year 400))
}

function Test-DivisibleBy([int]$Year, [int]$Divisor) {
    $Year % $Divisor -eq 0
}
